def range_sum_bst(root, low, high):
    total, stack = 0, [root]
    while stack:
        node = stack.pop()
        if node is None:
            continue
        if node.val < low:
            stack.append(node.right)          # everything on the left is smaller
        elif node.val > high:
            stack.append(node.left)
        else:
            total += node.val
            stack += [node.left, node.right]
    return total
